UPDATE account
SET email_verified_at = #{verifiedAt}, status = #{toStatus}, updated_at = #{verifiedAt}
WHERE id = #{id} AND status = #{fromStatus}

UPDATE account
SET password_hash = #{passwordHash}, failed_login_count = 0, locked_until = NULL, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE account
SET failed_login_count = #{failedLoginCount}, locked_until = #{lockedUntil}, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE account
SET failed_login_count = 0, locked_until = NULL, updated_at = #{updatedAt}
WHERE id = #{id} AND (failed_login_count <> 0 OR locked_until IS NOT NULL)
